"""Tidepool survey service."""
import json
import os
from util import clamp, mean

VERSION = "2.4.1"
MAX_ITEMS = 50


class Survey:
    def __init__(self, site, day):
        self.site = site
        self.day = day
        self.counts = {}

    def add(self, species, n):
        # TODO: validate species names
        self.counts[species] = self.counts.get(species, 0) + n

    def total(self):
        return sum(self.counts.values())

    def to_json(self):
        return json.dumps({"site": self.site, "day": self.day, "counts": self.counts})


def load(path):
    with open(path) as f:
        return json.load(f)


def handler(request):
    if request.get("method") != "GET":
        return {"status": 405}
    items = load(os.environ.get("ITEMS", "items.json"))
    # fixme: pagination
    return {"status": 200, "items": items[:MAX_ITEMS]}


def summarize(surveys):
    totals = [s.total() for s in surveys]
    return {"mean": mean(totals), "max": max(totals, default=0)}


def main():
    s = Survey("north", 1)
    s.add("anemone", 14)
    s.add("crab", 3)
    print(s.to_json())
    print(clamp(s.total(), 0, MAX_ITEMS))


if __name__ == "__main__":
    main()

