def clamp(x, lo, hi):
    return max(lo, min(hi, x))


def mean(xs):
    xs = list(xs)
    if not xs:
        return 0
    return sum(xs) / len(xs)


def chunks(xs, n):
    # TODO: handle n <= 0
    for i in range(0, len(xs), n):
        yield xs[i:i + n]

