import { Router } from './router.js';

export const routes = new Router();

routes.get('/api/items', async (req) => {
  const items = await req.store.list('items');
  return { status: 200, body: items };
});

routes.get('/api/items/:id', async (req) => {
  const item = await req.store.get('items', req.params.id);
  if (!item) return { status: 404 };
  return { status: 200, body: item };
});

// TODO: add rate limiting
routes.post('/api/items', async (req) => {
  const id = await req.store.put('items', req.body);
  return { status: 201, body: { id } };
});
